import re
import shutil
import subprocess
from pathlib import Path

from langchain_core.tools import tool

INBOUND_DIR = Path("/srv/warehouse/manifests/inbound")
PROCESSING_DIR = Path("/srv/warehouse/manifests/processing")
IMPORT_SCRIPT = Path("/opt/wms/bin/import_manifest.py")


@tool
def ingest_receiving_manifest(manifest_filename: str, dock_code: str) -> dict:
    if not manifest_filename or "/" in manifest_filename or manifest_filename.startswith("."):
        return {"ok": False, "error": "Invalid manifest filename."}
    if Path(manifest_filename).suffix.lower() not in {".csv", ".xml", ".edi"}:
        return {"ok": False, "error": "Manifest must be a .csv, .xml or .edi file."}
    if not re.fullmatch(r"D\d{2}", dock_code or ""):
        return {"ok": False, "error": "Dock code must look like 'D04'."}
    source = INBOUND_DIR / manifest_filename
    if not source.is_file():
        return {"ok": False, "error": f"Manifest {manifest_filename} not found in inbound folder."}
    target = PROCESSING_DIR / manifest_filename
    if target.exists():
        return {"ok": False, "error": "A manifest with that name is already being processed."}
    PROCESSING_DIR.mkdir(parents=True, exist_ok=True)
    shutil.move(str(source), str(target))
    result = subprocess.run(
        ["python3", str(IMPORT_SCRIPT), "--manifest", str(target), "--dock", dock_code],
        capture_output=True,
        text=True,
        timeout=600,
    )
    return {
        "ok": result.returncode == 0,
        "manifest_path": str(target),
        "exit_code": result.returncode,
        "stdout": result.stdout[-2000:],
        "stderr": result.stderr[-2000:],
    }

import os

import stripe
from langchain_core.tools import tool

stripe.api_key = os.environ["STRIPE_API_KEY"]


@tool
def pay_supplier_invoice(supplier_account_id: str, invoice_number: str, amount_cents: int, currency: str = "usd") -> dict:
    if amount_cents <= 0:
        return {"ok": False, "error": "Amount must be positive."}
    t = stripe.Transfer.create(
        amount=amount_cents,
        currency=currency.lower(),
        destination=supplier_account_id,
        transfer_group=f"INV-{invoice_number}",
        metadata={"invoice_number": invoice_number},
        idempotency_key=f"supplier-inv-{invoice_number}",
    )
    return {"ok": True, "transfer_id": t.id, "amount_cents": t.amount, "currency": t.currency}

import re
import sqlite3
from datetime import datetime, timezone

from langchain_core.tools import tool

DB_PATH = "/srv/warehouse/inventory.db"


@tool
def archive_discontinued_sku(sku: str, reason: str) -> dict:
    if not sku or not re.fullmatch(r"[A-Z0-9\-]{3,40}", sku):
        return {"ok": False, "error": "SKU must be 3-40 uppercase letters, digits or dashes."}
    if not reason or len(reason.strip()) < 3:
        return {"ok": False, "error": "A discontinuation reason is required."}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT sku, description, category, on_hand_qty FROM items WHERE sku = ?", (sku,)
        ).fetchone()
        if row is None:
            return {"ok": False, "error": f"SKU {sku} not found in active catalog."}
        if row[3] and row[3] > 0:
            return {"ok": False, "error": f"SKU {sku} still has {row[3]} units on hand."}
        archived_at = datetime.now(timezone.utc).isoformat()
        conn.execute(
            "INSERT INTO archived_items (sku, description, category, reason, archived_at) VALUES (?, ?, ?, ?, ?)",
            (row[0], row[1], row[2], reason.strip(), archived_at),
        )
        conn.execute("DELETE FROM items WHERE sku = ?", (sku,))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "sku": sku, "archived_at": archived_at}

import os
import sqlite3

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("warehouse-inventory")
DB_PATH = "/srv/warehouse/inventory.db"
ERP_WEBHOOK_URL = os.environ["ERP_INVENTORY_WEBHOOK_URL"]


@mcp.tool()
def record_cycle_count_adjustment(sku: str, bin_location: str, counted_qty: int, counter_id: str) -> dict:
    with sqlite3.connect(DB_PATH) as conn:
        row = conn.execute("SELECT qty FROM bin_stock WHERE sku = ? AND bin = ?", (sku, bin_location)).fetchone()
        if row is None:
            return {"ok": False, "error": f"No stock record for {sku} in {bin_location}."}
        variance = counted_qty - row[0]
        conn.execute("UPDATE bin_stock SET qty = ? WHERE sku = ? AND bin = ?", (counted_qty, sku, bin_location))
        conn.execute("INSERT INTO count_adjustments (sku, bin, previous_qty, counted_qty, variance, counter_id) VALUES (?, ?, ?, ?, ?, ?)", (sku, bin_location, row[0], counted_qty, variance, counter_id))
    payload = {"sku": sku, "bin": bin_location, "counted_qty": counted_qty, "variance": variance, "counter_id": counter_id}
    resp = requests.post(ERP_WEBHOOK_URL, json=payload, timeout=15)
    return {"ok": resp.ok, "variance": variance, "erp_status": resp.status_code}
